@RestController
@RequestMapping("/api/v1/users")
public class UserController {
    private final UserService userService;

    @GetMapping  // GET /api/v1/users
    public List<UserDto> getAllUsers() {
        return userService.findAll();
    }

    @GetMapping("/{userId}")  // GET /api/v1/users/42
    public UserDto getUser(@PathVariable Long userId) {
        return userService.findById(userId);
    }

    @GetMapping("/{userId}/orders")  // Nested resource hierarchy
    public List<OrderDto> getUserOrders(@PathVariable Long userId) {
        return userService.findOrdersByUserId(userId);
    }

    @PostMapping  // POST /api/v1/users (verb in method, not URI)
    public UserDto createUser(@RequestBody UserDto user) {
        return userService.create(user);
    }
}

@RestController
@RequestMapping("/api/v1/orders")  // Version 1 controller
public class OrderControllerV1 {
    @GetMapping("/{orderId}")
    public OrderDtoV1 getOrder(@PathVariable Long orderId) {
        // V1 returns basic fields only
        return new OrderDtoV1(orderId, "Product A", 99.99);
    }
}

@RestController
@RequestMapping("/api/v2/orders")  // Version 2 with breaking changes
public class OrderControllerV2 {
    @GetMapping("/{orderId}")
    public OrderDtoV2 getOrder(@PathVariable Long orderId) {
        // V2 renamed 'price' to 'totalAmount' (breaking change)
        return new OrderDtoV2(orderId, "Product A", 99.99, "USD");
    }
}

record OrderDtoV1(Long id, String product, Double price) {}
record OrderDtoV2(Long id, String product, Double totalAmount, String currency) {}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @GetMapping("/{orderId}")
    public EntityModel<OrderDto> getOrder(@PathVariable Long orderId) {
        var order = new OrderDto(orderId, "Laptop", "SHIPPED");

        // Add hypermedia links based on order state
        var model = EntityModel.of(order);
        model.add(linkTo(methodOn(OrderController.class)
            .getOrder(orderId)).withSelfRel());

        if (order.status().equals("SHIPPED")) {
            // Conditionally include action links
            model.add(linkTo(methodOn(OrderController.class)
                .trackOrder(orderId)).withRel("track"));
        }

        return model;  // Client discovers available actions from links
    }
}

record OrderDto(Long id, String product, String status) {}

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ProblemDetail> handleValidation(
            MethodArgumentNotValidException ex) {
        var problem = ProblemDetail.forStatusAndDetail(
            HttpStatus.BAD_REQUEST, 
            "Validation failed for one or more fields"
        );
        problem.setType(URI.create("/errors/validation-failed"));
        problem.setTitle("Validation Failed");

        // Add field-level errors for client to highlight form fields
        var errors = ex.getBindingResult().getFieldErrors().stream()
            .map(err -> Map.of("field", err.getField(), 
                              "message", err.getDefaultMessage()))
            .toList();
        problem.setProperty("fieldErrors", errors);

        return ResponseEntity.badRequest().body(problem);
    }
}
